let currentUser=null,needsSetup=false,routeVersion=0;
async function api(url,method='GET',body){const r=await fetch('/api/'+url,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw new Error(data.error||'Não foi possível carregar.');return data;}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const dateLabel=d=>new Date(d).toLocaleDateString('pt-BR');
function authView(admin=false,register=false){if(admin)return `<section class="admin-auth admin-login"><form data-account-form="login" data-admin="true" aria-label="Acesso administrativo">${field('Login','email','','email','required maxlength="160" autocomplete="username"')}${field('Senha','password','','password','required maxlength="128" autocomplete="current-password"')}<p class="form-error" role="alert"></p><button class="btn dark" type="submit">Entrar</button></form></section>`;const setup=admin&&needsSetup;return `<section class="auth-layout ${admin?'admin-auth':''}"><div class="auth-intro"><div class="eyebrow">${admin?'GESTÃO MS ATACADO':'ÁREA DE LOJISTAS'}</div><h1>${admin?'Gestão da loja':'Acesse sua<br>conta na MS.'}</h1><p>${admin?'Organize o catálogo, acompanhe pedidos e clientes.':'Salve seus pedidos e acompanhe seu histórico na loja.'}</p><img src="/assets/hero.webp" alt="Peças de jeans dobradas"></div><div class="auth-panel"><div class="eyebrow">${setup?'PRIMEIRO ACESSO':register?'CADASTRO':'ACESSO'}</div><h2>${setup?'Criar administrador':register?'Criar conta':admin?'Entrar no painel':'Entrar'}</h2><form data-account-form="${setup?'setup':register?'register':'login'}" data-admin="${admin}">${setup||register?field('Nome','name','','text','required minlength="2" maxlength="100" autocomplete="name"'):''}${field('E-mail','email','','email','required maxlength="160" autocomplete="username"')}${field('Senha','password','','password',`required minlength="10" maxlength="128" autocomplete="${register||setup?'new-password':'current-password'}"`)}<small>Mínimo de 10 caracteres.</small><p class="form-error" role="alert"></p><button class="btn dark" type="submit">${setup?'Criar acesso':register?'Criar minha conta':'Entrar'}</button></form>${admin?'':`<p class="auth-switch">${register?'Já tem conta? <a href="#conta">Entrar</a>':'Ainda não tem conta? <a href="#cadastro">Cadastre-se</a>'}</p>`}<a class="text-link" href="#catalogo">Voltar ao catálogo</a></div></section>`;}
function shell(title,subtitle,content,admin=false){const links=admin?[['admin','Visão geral'],['admin/pedidos','Pedidos'],['admin/produtos','Catálogo'],['admin/clientes','Clientes']]:[['conta','Meus pedidos'],['conta/dados','Meus dados']];return `<div class="workspace"><aside class="account-sidebar"><div class="eyebrow">${admin?'ADMINISTRAÇÃO':'MINHA CONTA'}</div><strong>${esc(currentUser.name)}</strong><small>${esc(currentUser.email)}</small><nav aria-label="Menu da conta">${links.map(([href,label])=>`<a class="${location.hash==='#'+href?'selected':''}" href="#${href}">${label}</a>`).join('')}</nav><div class="sidebar-footer"><a href="#catalogo">Ver catálogo</a><button class="logout" data-logout>Sair</button></div></aside><section class="account-content"><div class="account-head"><div><div class="eyebrow">MS ATACADO · ${admin?'GESTÃO':'CLIENTE'}</div><h1>${title}</h1>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div></div>${content}</section></div>`;}
function orderCards(orders,admin=false){return orders.length?orders.map(o=>`<article class="order-card"><div class="order-heading"><div><strong>Pedido #${o.id.slice(0,8).toUpperCase()}</strong><small>${dateLabel(o.created)} · ${o.items.reduce((s,i)=>s+i.qty,0)} peças</small>${admin?`<p>${esc(o.name)} · ${esc(o.email)}</p>`:''}</div><span class="status-pill">${esc(o.status)}</span></div><details><summary>Peças do pedido (${o.items.reduce((s,i)=>s+i.qty,0)})</summary>${o.items.map(i=>`<div class="order-item"><img src="${productImage(i.image)}" alt=""><div><strong>${esc(i.name)}</strong><p>Tamanho ${esc(i.size)}</p></div><span>${i.qty} un.</span></div>`).join('')}</details>${admin?`<form data-status="${o.id}" class="status-form"><label>Situação <select name="status">${['Salvo','Em análise','Concluído','Cancelado'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></label><button class="btn outline">Atualizar</button><span class="form-error" role="alert"></span></form>`:''}</article>`).join(''):'<div class="account-empty"><span class="empty-number">06</span><h2>Nenhum pedido salvo</h2><p>Monte seu pedido no catálogo a partir de 6 peças.</p><a class="btn" href="#catalogo">Ver catálogo</a></div>';}
const originalRoute=route;
window.removeEventListener('hashchange',originalRoute);
route=async function(){const version=++routeVersion;const adminPath=/^\/msadm\/?$/.test(location.pathname);const page=location.hash.slice(1)||(adminPath?'admin':'inicio');if(page.startsWith('admin')&&!adminPath){location.replace('/msadm'+(page==='admin'?'':'#'+page));return;}if(adminPath&&!page.startsWith('admin')){location.assign('/#'+page);return;}if(!/^(conta|cadastro|admin)(\/|$)/.test(page)){try{await loadProducts();if(version===routeVersion)originalRoute();}catch(e){toast(e.message);}return;}main.innerHTML='<section class="info-page"><p role="status">Carregando sua área…</p></section>';window.scrollTo(0,0);try{const session=await api('session');if(version!==routeVersion)return;currentUser=session.user;needsSetup=session.setupNeeded;const admin=page.startsWith('admin');document.title='MS Atacado — '+(admin?'Painel administrativo':'Minha conta');if(!currentUser||(admin&&!session.adminAuthenticated)){main.innerHTML=authView(admin,page==='cadastro');return;}if(admin&&currentUser.role!=='admin'){main.innerHTML=shell('Acesso restrito','Esta conta não tem acesso ao painel.','<a class="btn" href="#conta">Ir para minha conta</a>');return;}
 if(admin){await loadProducts();const data=await api('admin/overview');if(version!==routeVersion)return;let content,title,subtitle='';
 if(page==='admin/produtos'){title='Seu catálogo.';subtitle='Organize suas peças, fotos e estoque.';content=catalogAdmin();}
 else if(page==='admin/clientes'){title='Clientes';content=data.customers.length?`<div class="customer-list">${data.customers.map(c=>`<article class="order-card"><strong>${esc(c.name)}</strong><p>${esc(c.email)}</p><small>Desde ${dateLabel(c.created)} · ${data.orders.filter(o=>o.user_id===c.id).length} pedidos</small></article>`).join('')}</div>`:'<div class="account-empty"><h2>Nenhum cliente cadastrado</h2></div>';}
 else if(page==='admin/pedidos'){title='Pedidos';content=orderCards(data.orders,true);}
 else{title='Visão geral';content=`<div class="stats"><article><span>Pedidos</span><strong>${data.orders.length}</strong></article><article><span>Clientes</span><strong>${data.customers.length}</strong></article><article><span>Modelos</span><strong>${products.length}</strong></article></div><div class="dashboard-banner"><div><h2>Gerenciar catálogo</h2><p>Atualize fotos, descrições e grade disponível por tamanho.</p></div><a class="btn" href="#admin/produtos">Editar catálogo</a></div><h2>Pedidos recentes</h2>${orderCards(data.orders.slice(0,3),true)}`;}
 main.innerHTML=shell(title,subtitle,content,true);if(page==='admin/produtos')renderAdminList();
 }else if(page==='conta/dados'){main.innerHTML=shell('Meus dados','',`<form data-account-form="profile" class="profile-form">${field('Nome','name',currentUser.name,'text','required minlength="2" maxlength="100"')}${field('E-mail','email',currentUser.email,'email','disabled')}<p class="form-error" role="alert"></p><button class="btn dark">Salvar dados</button></form>`);}
 else{const orders=await api('orders');if(version!==routeVersion)return;main.innerHTML=shell('Meus pedidos','',orderCards(orders));}
 }catch(e){if(version===routeVersion)main.innerHTML=`<section class="info-page"><h1>Não foi possível carregar.</h1><p>${esc(e.message)}</p><button class="btn" data-retry>Tentar novamente</button></section>`;}};
window.addEventListener('hashchange',route);
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('[data-account-form],[data-product],[data-status]'))return;e.preventDefault();const button=form.querySelector('button:not([type="button"])');button.disabled=true;const error=form.querySelector('.form-error');error.textContent='';try{const values=Object.fromEntries(new FormData(form));if(form.dataset.accountForm){const action=form.dataset.accountForm;const endpoint=action==='login'&&form.dataset.admin==='true'?'admin/login':action;const result=await api(endpoint,action==='profile'?'PATCH':'POST',values);if(action!=='profile'){const confirmed=await api('session');if(!confirmed.user)throw new Error('O navegador não manteve seu login. Permita cookies para este endereço e tente novamente.');}currentUser=result.user;if(action==='profile'){toast('Dados atualizados.');}else{location.hash=form.dataset.admin==='true'?'admin':'conta';await route();if(sessionStorage.getItem('ms-save-after-login')){sessionStorage.removeItem('ms-save-after-login');renderCart();dialog.showModal();}}}else if(form.dataset.product){values.variants=[...form.querySelectorAll('.stock-row')].map(row=>({size:row.querySelector('[data-stock-size]').value,quantity:Number(row.querySelector('[data-stock-quantity]').value)}));values.inventoryVersion=Number(form.querySelector('[data-version]').dataset.version);await api('admin/admin/products'.replace('admin/admin','admin')+'/'+form.dataset.product,'PATCH',values);await loadProducts();form.querySelector('[data-version]').dataset.version=products.find(p=>p.id===form.dataset.product).inventoryVersion;toast('Catálogo atualizado.');}else{await api('admin/orders/'+form.dataset.status,'PATCH',values);await route();toast('Situação atualizada.');}}catch(err){error.textContent=err.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-retry'))route();if(el.hasAttribute('data-logout')){try{await api('logout','POST',{});currentUser=null;await route();}catch(err){toast(err.message);}}},false);
// Intercept review before the existing demo-only cart handler.
document.addEventListener('click',async e=>{const button=e.target.closest('[data-review],[data-save-order]');if(!button)return;e.stopImmediatePropagation();if(cart.reduce((s,i)=>s+i.qty,0)<6)return;button.disabled=true;try{const session=await api('session');currentUser=session.user;if(!currentUser){sessionStorage.setItem('ms-save-after-login','1');dialog.close();location.hash='conta';await route();return;}if(button.hasAttribute('data-review')){document.querySelector('#cart-body').innerHTML=`<div class="success"><h3>Confirmar pedido?</h3><p>${cart.reduce((s,i)=>s+i.qty,0)} peças selecionadas para ${esc(currentUser.name)}.</p></div><button class="btn dark" data-save-order>Salvar pedido na minha conta</button><button class="btn outline" data-back-cart>Voltar às peças</button>`;}else{await api('orders','POST',{items:cart});cart=[];save();await loadProducts();dialog.close();location.hash='conta';await route();toast('Pedido salvo na sua conta.');}}catch(err){toast(err.message);}finally{button.disabled=false;}},true);
async function loadProducts(){const list=await api('products');products.splice(0,products.length,...list);}
loadProducts().then(()=>route()).catch(()=>{toast('Não foi possível conectar ao servidor local.');route();});
